parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "property_type": {
      "type": "string",
      "description": "The property type mentioned in the text. Use lowercase values such as apartment, house, villa, studio, office, retail, industrial, warehouse, land, or commercial. If unclear, return unknown. Never return null."
    },
    "location": {
      "type": "string",
      "description": "The city, neighborhood, street, or area mentioned in the text. If not mentioned, return —. Never return null."
    },
    "price": {
      "type": "string",
      "description": "The property price exactly as written, including currency and payment period if present. If not mentioned, return —. Never return null."
    },
    "number_of_rooms": {
      "type": "string",
      "description": "The number of rooms exactly as written, for example 3 rooms, 3-bedroom, 4.5 rooms, or two meeting rooms. For commercial properties with no room count mentioned, return —. Never return null."
    },
    "key_features": {
      "type": "array",
      "description": "Important property features explicitly mentioned in the text, such as size, renovation status, balcony, view, parking, elevator, storage, basement, high foot traffic, lease terms, bathrooms, meeting rooms, or kitchenette. Return an empty array if none are mentioned.",
      "items": {
        "type": "string"
      }
    },
    "certifications": {
      "type": "array",
      "description": "Certifications explicitly mentioned in the text, such as energy rating, LEED, earthquake-resistant construction, or other formal certifications. Return an empty array if none are mentioned.",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "property_type",
    "location",
    "price",
    "number_of_rooms",
    "key_features",
    "certifications"
  ],
  "additionalProperties": false
}

parameters.text:
=Analyze this property submission using only the LangGraph_Agent tool.

Original description:
{{ $('Webhook').first().json.body.description }}

Extracted fields:
{{ JSON.stringify($('Information Extractor').first().json.output) }}

Image context:
Image URL count: {{ $('Webhook').first().json.body.image_urls?.length || 0 }}
Uploaded image count: {{ $('Webhook').first().json.body.uploaded_images?.length || 0 }}
Image URL exists: {{ ($('Webhook').first().json.body.image_urls?.length || 0) > 0 ? "YES" : "NO" }}
Uploaded image exists: {{ ($('Webhook').first().json.body.uploaded_images?.length || 0) > 0 ? "YES" : "NO" }}

Image URLs:
{{ JSON.stringify($('Webhook').first().json.body.image_urls || []) }}

Uploaded images:
{{ JSON.stringify(($('Webhook').first().json.body.uploaded_images || []).map(img => ({
  filename: img.filename,
  mime_type: img.mime_type,
  has_base64: !!img.base64
}))) }}

Mandatory tool usage:
- You MUST call only the LangGraph_Agent tool.
- Do NOT call rag_service.
- Do NOT call image_analyser.
- LangGraph_Agent is responsible for calling RAG and Image Analyser internally.
- Send the property description, image URLs, and uploaded images to LangGraph_Agent.
- If both image URLs and uploaded images exist, send both to LangGraph_Agent.
- Do not generate the final user-facing report.
- Return only the enrichment JSON after receiving the LangGraph_Agent result.

parameters.jsonBody:
={
  "query": "Analyze this property and provide renovation priorities, improvement suggestions, and missing information. Do not write the final report.",
  "description": {{ JSON.stringify($('Webhook').first().json.body.description || "") }},
  "image_urls": {{ JSON.stringify($('Webhook').first().json.body.image_urls || []) }},
  "images": {{ JSON.stringify(($('Webhook').first().json.body.uploaded_images || []).map(img => ({
    image_base64: img.base64,
    mime_type: img.mime_type,
    filename: img.filename
  }))) }}
}

parameters.responseBody:
{
  "status": "blocked",
  "message": "The generated report requires human review.",
  "reason": "{{ $('Guardrails Output Check').first().json.reason }}"
}

={{
(() => {
  const info = $("Information Extractor").first().json.output || {};
  const propertyType = info.property_type || "Not provided";
  const description = $("Webhook").first().json.body?.description || "";

  const combinedText = `${propertyType} ${description}`.toLowerCase();

  const isCommercial =
    combinedText.includes("commercial") ||
    combinedText.includes("office") ||
    combinedText.includes("retail") ||
    combinedText.includes("industrial") ||
    combinedText.includes("warehouse") ||
    combinedText.includes("shop") ||
    combinedText.includes("store") ||
    combinedText.includes("clinic") ||
    combinedText.includes("restaurant") ||
    combinedText.includes("workspace");

  return {
    status: "success",
    team: isCommercial ? "commercial" : "residential",
    property_type: propertyType,
    message: "Property report generated successfully.",
    report:
      $("Guardrails Output Check").first().json.safe_text ||
      $("Basic LLM Chain").first().json.text ||
      ""
  };
})()
}}
